import{_ as e,o as l,c as o,al as i}from"./chunks/framework.BfjwFeD9.js";const b=JSON.parse('{"title":"Packages","description":"","frontmatter":{"outline":"deep","head":[["meta",{"name":"og:title","content":"Packages | ProzillaOS Docs"}],["meta",{"name":"twitter:title","content":"Packages | ProzillaOS Docs"}],["meta",{"name":"og:description","content":"Documentation for ProzillaOS and its packages."}],["meta",{"name":"twitter:description","content":"Documentation for ProzillaOS and its packages."}],["link",{"rel":"canonical","href":"https://os.prozilla.dev/docs/reference/packages"}],["meta",{"name":"og:url","content":"https://os.prozilla.dev/docs/reference/packages"}],["meta",{"name":"twitter:url","content":"https://os.prozilla.dev/docs/reference/packages"}],["meta",{"name":"og:locale","content":"en_US"}],["meta",{"name":"og:image","content":"https://os.prozilla.dev/docs/prozilla-os-title-banner.png"}],["meta",{"name":"twitter:image","content":"https://os.prozilla.dev/docs/prozilla-os-title-banner.png"}],["meta",{"name":"og:type","content":"website"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"reference/packages.md","filePath":"reference/packages.md"}'),s={name:"reference/packages.md"};function t(r,a,n,c,d,p){return l(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to “Packages”">​</a></h1><p>This is an overview of all packages related to ProzillaOS. Each package is published to the npm registry.</p><h2 id="bundle" tabindex="-1">Bundle <a class="header-anchor" href="#bundle" aria-label="Permalink to “Bundle”">​</a></h2><p>This bundle lets you quickly get started with ProzillaOS without the hassle of installing all packages individually.</p><ul><li><a href="./prozilla-os/" data-symbol="prozilla-os" class="symbol-link inline-symbol-link package-symbol"><code>prozilla-os</code></a>: A bundle containing <a href="/docs/reference/core/" data-symbol="@prozilla-os/core" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/core</code></a>, <a href="/docs/reference/shared/" data-symbol="@prozilla-os/shared" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/shared</code></a> and all <a href="#primary-applications">primary applications</a> of ProzillaOS.</li></ul><h2 id="libraries" tabindex="-1">Libraries <a class="header-anchor" href="#libraries" aria-label="Permalink to “Libraries”">​</a></h2><p>These libraries are different modules of ProzillaOS that can be installed separately. <a href="/docs/reference/core/" data-symbol="@prozilla-os/core" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/core</code></a> and <a href="/docs/reference/shared/" data-symbol="@prozilla-os/shared" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/shared</code></a> are also included in the <a href="/docs/reference/prozilla-os/" data-symbol="prozilla-os" class="symbol-link inline-symbol-link package-symbol"><code>prozilla-os</code></a> bundle.</p><table tabindex="0"><thead><tr><th>Package</th><th>Description</th></tr></thead><tbody><tr><td><a href="./core/" data-symbol="@prozilla-os/core" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/core</code></a></td><td>Core functionality of ProzillaOS, with React components, hooks and a router.</td></tr><tr><td><a href="./skins/" data-symbol="@prozilla-os/skins" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/skins</code></a></td><td>Customizable skins for ProzillaOS that can override content and layout and dynamically load CSS.</td></tr><tr><td><a href="./shared/" data-symbol="@prozilla-os/shared" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/shared</code></a></td><td>Common generic TypeScript functions and utilities (e.g., data manipulation, logging), not directly related to ProzillaOS.</td></tr><tr><td><a href="./dev-tools/" data-symbol="@prozilla-os/dev-tools" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/dev-tools</code></a></td><td>Tools for the development of anything related to ProzillaOS (e.g., ProzillaOS websites, ProzillaOS apps). Used extensively for the development of official ProzillaOS packages (e.g., shared configurations, testing utilities).</td></tr></tbody></table><h2 id="applications" tabindex="-1">Applications <a class="header-anchor" href="#applications" aria-label="Permalink to “Applications”">​</a></h2><h3 id="primary-applications" tabindex="-1">Primary applications <a class="header-anchor" href="#primary-applications" aria-label="Permalink to “Primary applications”">​</a></h3><p>These applications are included in the <a href="/docs/reference/prozilla-os/" data-symbol="prozilla-os" class="symbol-link inline-symbol-link package-symbol"><code>prozilla-os</code></a> bundle.</p><table tabindex="0"><thead><tr><th>Package</th><th>Description</th></tr></thead><tbody><tr><td><a href="./apps/file-explorer/" data-symbol="@prozilla-os/file-explorer" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/file-explorer</code></a></td><td>File explorer app</td></tr><tr><td><a href="./apps/terminal/" data-symbol="@prozilla-os/terminal" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/terminal</code></a></td><td>Terminal/shell app</td></tr><tr><td><a href="./apps/text-editor/" data-symbol="@prozilla-os/text-editor" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/text-editor</code></a></td><td>Text editor app</td></tr><tr><td><a href="./apps/settings/" data-symbol="@prozilla-os/settings" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/settings</code></a></td><td>Settings app</td></tr><tr><td><a href="./apps/media-viewer/" data-symbol="@prozilla-os/media-viewer" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/media-viewer</code></a></td><td>Media viewer app</td></tr><tr><td><a href="./apps/browser/" data-symbol="@prozilla-os/browser" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/browser</code></a></td><td>Browser app</td></tr><tr><td><a href="./apps/calculator/" data-symbol="@prozilla-os/calculator" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/calculator</code></a></td><td>Calculator app</td></tr><tr><td><a href="./apps/app-center/" data-symbol="@prozilla-os/app-center" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/app-center</code></a></td><td>App center</td></tr></tbody></table><h3 id="secondary-applications" tabindex="-1">Secondary applications <a class="header-anchor" href="#secondary-applications" aria-label="Permalink to “Secondary applications”">​</a></h3><ul><li><a href="./apps/logic-sim/" data-symbol="@prozilla-os/logic-sim" class="symbol-link inline-symbol-link package-symbol"><code>@prozilla-os/logic-sim</code></a>: Logic simulator app</li></ul><h3 id="external-applications" tabindex="-1">External applications <a class="header-anchor" href="#external-applications" aria-label="Permalink to “External applications”">​</a></h3><p>These applications are related to ProzillaOS and used in the demo, but their source code is hosted in a separate repository on GitHub.</p><ul><li><a href="https://github.com/prozilla-os/ProzillaOS-games/blob/main/packages/games/minesweeper" target="_blank" rel="noreferrer"><code>@prozilla-os/minesweeper</code></a>: Minesweeper clone</li><li><a href="https://github.com/prozilla-os/ProzillaOS-games/blob/main/packages/games/wordle" target="_blank" rel="noreferrer"><code>@prozilla-os/wordle</code></a>: Wordle clone</li><li><a href="https://github.com/prozilla-os/ProzillaOS-games/blob/main/packages/games/ball-maze" target="_blank" rel="noreferrer"><code>@prozilla-os/ball-maze</code></a>: 3D wooden ball maze game</li><li><a href="https://github.com/prozilla-os/Bliss-radio-app" target="_blank" rel="noreferrer"><code>@prozilla-os/bliss-radio</code></a>: Radio app</li></ul>',17)])])}const h=e(s,[["render",t]]);export{b as __pageData,h as default};
